  for (;ptr && ptr->next; ptr = ptr->next) {
    if (((ptr->search_type == CHILD_SEARCH) && (ptr->next->search_type == CHILD)) ||
       ((ptr->search_type == MEMBER_SEARCH) && (ptr->next->search_type == MEMBER)) ||
